const items = $input.all();
const text1Lines = ($('HTTP Extract Text PDF 1').item.json.ParsedResults?.[0]?.ParsedText || '').split('\n');
const text2Lines = ($('HTTP Extract Text PDF 2').item.json.ParsedResults?.[0]?.ParsedText || '').split('\n');
const changes = [];
const maxLines = Math.max(text1Lines.length, text2Lines.length);
for (let i = 0; i < maxLines; i++) {
  const line1 = (text1Lines[i] || '').trim();
  const line2 = (text2Lines[i] || '').trim();
  if (line1 !== line2) {
    let changeType = 'modified';
    if (!line1 && line2) changeType = 'added';
    else if (line1 && !line2) changeType = 'removed';
    changes.push({
      json: {
        lineNumber: i + 1,
        changeType,
        pdf1Text: line1,
        pdf2Text: line2
      }
    });
  }
}
const summary = {
  json: {
    totalLines: maxLines,
    changedLines: changes.length,
    addedLines: changes.filter(c => c.json.changeType === 'added').length,
    removedLines: changes.filter(c => c.json.changeType === 'removed').length,
    modifiedLines: changes.filter(c => c.json.changeType === 'modified').length,
    similarityPercent: ((1 - changes.length / Math.max(maxLines, 1)) * 100).toFixed(1)
  }
};
return [summary, ...changes];

